export const envelope = [13, 18, 13];

export default function build(api) {
  const size = api.size;
  const SY = 4; // Node-local Y of the seat plane meeting ground

  // Theme-aware masonry & foundation palette with robust fallbacks
  const stonePrimary = api.theme.stone?.primary || "minecraft:polished_andesite";
  const stoneAccent = api.theme.stone?.accent || "minecraft:smooth_stone";
  const stoneWall = api.theme.stone?.wall || "minecraft:stone_brick_wall";
  const groundPlinth = api.theme.ground?.plinth || "minecraft:polished_deepslate";
  const groundRevet = api.theme.ground?.revetment || "minecraft:mossy_cobblestone";
  const groundPave = api.theme.ground?.pavement || "minecraft:smooth_stone";

  const stoneStairs = (facing, half = "bottom") => {
    const base = api.theme.stone?.stairs?.split("[")[0] || "minecraft:stone_brick_stairs";
    return `${base}[facing=${facing},half=${half}]`;
  };

  // Safe placement helpers
  function putAbs(x, y, z, block) {
    if (x >= 0 && x < size[0] && y >= 0 && y < size[1] && z >= 0 && z < size[2]) {
      api.set(x, y, z, block);
    }
  }

  function put(x, y_rel, z, block) {
    putAbs(x, SY + y_rel, z, block);
  }

  // Define generator foundation footprint
  const occupied = Array.from({ length: 13 }, () => Array(13).fill(false));

  for (let x = 0; x < 13; x++) {
    for (let z = 0; z < 13; z++) {
      const dx = x - 6;
      const dz = z - 6.5;
      if (dx * dx + dz * dz <= 24.5) {
        occupied[x][z] = true;
      }
    }
  }

  // Front operator terminal pit footprint
  for (let x = 4; x <= 8; x++) {
    for (let z = 1; z <= 3; z++) {
      occupied[x][z] = true;
    }
  }

  // Concrete ruins & subsystem wings
  const extraFootprint = [
    [2, 2], [2, 3], [3, 2], [1, 2],
    [10, 2], [10, 3], [9, 2], [11, 2],
    [2, 6], [2, 7], [2, 8], [2, 9], [3, 9], [3, 10], [2, 10], [1, 9],
    [9, 9], [9, 10], [10, 9], [10, 10], [8, 9], [9, 8], [11, 9], [10, 11]
  ];
  for (const [fx, fz] of extraFootprint) {
    if (fx >= 0 && fx < 13 && fz >= 0 && fz < 13) {
      occupied[fx][fz] = true;
    }
  }

  // 1. Conform to ground terrain at every occupied column
  for (let x = 0; x < 13; x++) {
    for (let z = 0; z < 13; z++) {
      if (!occupied[x][z]) continue;
      const h = api.heightAt(x, z);
      const groundY = Math.max(0, SY + Math.floor(h));

      if (groundY <= SY) {
        for (let y = groundY; y <= SY; y++) {
          let block = groundPlinth;
          if (y === groundY && ((x + z) % 3 === 0)) {
            block = groundRevet;
          } else if (y < SY && ((x * 7 + z * 13) % 5 === 0)) {
            block = "minecraft:cracked_stone_bricks";
          }
          putAbs(x, y, z, block);
        }
      } else {
        for (let y = SY; y <= groundY; y++) {
          putAbs(x, y, z, groundPlinth);
        }
      }
    }
  }

  // 2. Base Pavement & Inlaid Sub-floor Conduit Channels (y_rel = 0)
  for (let x = 0; x < 13; x++) {
    for (let z = 0; z < 13; z++) {
      if (occupied[x][z]) {
        if (x >= 3 && x <= 9 && z >= 3 && z <= 9) {
          put(x, 0, z, stoneAccent);
        } else {
          put(x, 0, z, stonePrimary);
        }
      }
    }
  }

  put(6, 0, 3, "minecraft:sea_lantern");
  put(6, 0, 4, "minecraft:sea_lantern");
  put(3, 0, 7, "minecraft:sea_lantern");
  put(4, 0, 7, "minecraft:sea_lantern");
  put(8, 0, 7, "minecraft:sea_lantern");
  put(9, 0, 7, "minecraft:sea_lantern");
  put(6, 0, 7, "minecraft:lodestone");

  // 3. Floor Walkways, Curbs & Conduit Grates (y_rel = 1)
  put(5, 1, 2, groundPave);
  put(6, 1, 2, groundPave);
  put(7, 1, 2, groundPave);
  put(6, 1, 1, stoneStairs("south", "bottom"));

  put(6, 1, 3, "minecraft:iron_trapdoor[facing=north,half=bottom,open=false]");
  put(6, 1, 4, "minecraft:iron_trapdoor[facing=north,half=bottom,open=false]");
  put(3, 1, 7, "minecraft:iron_trapdoor[facing=east,half=bottom,open=false]");
  put(9, 1, 7, "minecraft:iron_trapdoor[facing=west,half=bottom,open=false]");

  const curbs = [
    [4, 1, 4], [5, 1, 4], [7, 1, 4], [8, 1, 4],
    [3, 1, 5], [9, 1, 5],
    [3, 1, 8], [9, 1, 8],
    [4, 1, 10], [5, 1, 10], [6, 1, 10], [7, 1, 10], [8, 1, 10]
  ];
  for (const [cx, cz] of curbs) {
    put(cx, 1, cz, stonePrimary);
  }

  put(5, 1, 3, groundPlinth);
  put(6, 1, 3, groundPlinth);
  put(7, 1, 3, groundPlinth);

  put(6, 1, 7, "minecraft:crying_obsidian");
  put(5, 1, 7, "minecraft:crying_obsidian");
  put(7, 1, 7, "minecraft:crying_obsidian");
  put(6, 1, 6, "minecraft:crying_obsidian");
  put(6, 1, 8, "minecraft:crying_obsidian");
  put(5, 1, 6, "minecraft:copper_block");
  put(7, 1, 6, "minecraft:copper_block");
  put(5, 1, 8, "minecraft:copper_block");
  put(7, 1, 8, "minecraft:copper_block");

  put(4, 1, 5, groundPlinth);
  put(8, 1, 5, groundPlinth);
  put(4, 1, 9, groundPlinth);
  put(8, 1, 9, groundPlinth);

  put(2, 1, 2, stonePrimary);
  put(2, 1, 3, stonePrimary);
  put(3, 1, 2, stonePrimary);

  put(10, 1, 2, stonePrimary);
  put(10, 1, 3, stonePrimary);
  put(9, 1, 2, stonePrimary);

  put(2, 1, 9, stonePrimary);
  put(2, 1, 10, stonePrimary);
  put(3, 1, 10, stonePrimary);

  put(9, 1, 9, groundPlinth);
  put(10, 1, 9, groundPlinth);
  put(9, 1, 10, groundPlinth);
  put(10, 1, 10, groundPlinth);

  // 4. Operator Terminal & Fortified Control Console (y_rel = 2 to 3)
  put(5, 2, 3, "minecraft:observer[facing=north]");
  put(6, 2, 3, "minecraft:target");
  put(7, 2, 3, "minecraft:comparator[facing=south,powered=true]");

  put(5, 3, 3, "minecraft:iron_trapdoor[facing=north,half=bottom,open=false]");
  put(6, 3, 3, stoneStairs("south", "top"));
  put(7, 3, 3, "minecraft:iron_trapdoor[facing=north,half=bottom,open=false]");

  put(6, 1, 2, stoneStairs("north", "bottom"));

  put(4, 2, 3, "minecraft:lightning_rod[facing=up]");
  put(8, 2, 3, "minecraft:lightning_rod[facing=up]");

  // 5. Ruined Concrete Columns & Blast Walls
  put(2, 2, 2, stonePrimary);
  put(2, 3, 2, "minecraft:cracked_stone_bricks");
  put(2, 4, 2, stoneWall);
  put(2, 2, 3, stoneWall);
  put(3, 2, 2, stoneStairs("east", "bottom"));

  put(10, 2, 2, stonePrimary);
  put(10, 3, 2, stonePrimary);
  put(10, 4, 2, stoneWall);
  put(9, 2, 2, stoneWall);
  put(10, 2, 3, stoneStairs("south", "bottom"));

  put(2, 2, 9, stonePrimary);
  put(2, 3, 9, stoneWall);
  put(3, 2, 10, stoneWall);
  put(2, 2, 10, stonePrimary);

  put(4, 2, 10, stoneWall);
  put(5, 2, 10, stonePrimary);
  put(6, 2, 10, stonePrimary);
  put(7, 2, 10, stonePrimary);
  put(8, 2, 10, stoneWall);
  put(5, 3, 10, stoneStairs("north", "bottom"));
  put(6, 3, 10, stoneWall);
  put(7, 3, 10, stoneStairs("north", "bottom"));

  // 6. West Coolant Radiator Subsystem (x=2..3, z=6..8)
  put(2, 2, 7, "minecraft:hopper[facing=east]");
  put(3, 2, 7, "minecraft:iron_block");
  put(2, 2, 6, "minecraft:iron_bars");
  put(2, 2, 8, "minecraft:iron_bars");
  put(3, 2, 6, "minecraft:copper_block");
  put(3, 2, 8, "minecraft:copper_block");

  put(2, 3, 6, "minecraft:iron_bars");
  put(2, 3, 8, "minecraft:iron_bars");
  put(2, 3, 7, "minecraft:iron_trapdoor[facing=north,half=bottom,open=false]");
  put(3, 3, 6, "minecraft:cut_copper_slab[type=bottom]");
  put(3, 3, 7, "minecraft:iron_bars");
  put(3, 3, 8, "minecraft:cut_copper_slab[type=bottom]");
  put(3, 4, 7, "minecraft:iron_bars");

  // 7. East Capacitor & Power Shunt Bank (x=9..10, z=6..8)
  put(9, 2, 6, "minecraft:crying_obsidian");
  put(9, 2, 7, "minecraft:iron_block");
  put(9, 2, 8, "minecraft:crying_obsidian");
  put(10, 2, 6, "minecraft:copper_block");
  put(10, 2, 7, "minecraft:copper_block");
  put(10, 2, 8, "minecraft:copper_block");

  put(9, 3, 6, "minecraft:daylight_detector");
  put(9, 3, 7, "minecraft:lightning_rod[facing=up]");
  put(9, 3, 8, "minecraft:daylight_detector");
  put(10, 3, 6, "minecraft:cut_copper_slab[type=bottom]");
  put(10, 3, 7, "minecraft:iron_bars");
  put(10, 3, 8, "minecraft:cut_copper_slab[type=bottom]");

  // 8. Fusion Core Reactor Vessel & Magnetic Containment (y_rel = 2 to 9)
  const pylons = [[4, 5], [8, 5], [4, 9], [8, 9]];
  for (const [px, pz] of pylons) {
    put(px, 2, pz, "minecraft:polished_deepslate");
    put(px, 3, pz, "minecraft:copper_block");
    put(px, 4, pz, "minecraft:cut_copper");
    put(px, 5, pz, "minecraft:copper_block");
    put(px, 6, pz, "minecraft:polished_deepslate");
    put(px, 7, pz, stoneWall);
  }

  put(6, 2, 7, "minecraft:crying_obsidian");
  put(6, 3, 7, "minecraft:sea_lantern");
  put(6, 4, 7, "minecraft:sea_lantern");
  put(6, 5, 7, "minecraft:sea_lantern");
  put(6, 6, 7, "minecraft:crying_obsidian");

  const cardinalCore = [[5, 7], [7, 7], [6, 6], [6, 8]];
  for (const [cx, cz] of cardinalCore) {
    put(cx, 2, cz, "minecraft:cut_copper");
    put(cx, 3, cz, "minecraft:cyan_stained_glass");
    put(cx, 4, cz, "minecraft:cyan_stained_glass");
    put(cx, 5, cz, "minecraft:cyan_stained_glass");
    put(cx, 6, cz, "minecraft:cut_copper");
  }

  const diagCore = [[5, 6], [7, 6], [5, 8], [7, 8]];
  for (const [dx, dz] of diagCore) {
    put(dx, 2, dz, "minecraft:iron_block");
    put(dx, 3, dz, "minecraft:iron_bars");
    put(dx, 4, dz, "minecraft:copper_block");
    put(dx, 5, dz, "minecraft:iron_bars");
    put(dx, 6, dz, "minecraft:iron_block");
  }

  // Toroidal magnetic confinement rings
  put(5, 2, 5, "minecraft:cut_copper_slab[type=bottom]");
  put(6, 2, 5, "minecraft:copper_block");
  put(7, 2, 5, "minecraft:cut_copper_slab[type=bottom]");
  put(5, 2, 9, "minecraft:cut_copper_slab[type=bottom]");
  put(6, 2, 9, "minecraft:copper_block");
  put(7, 2, 9, "minecraft:cut_copper_slab[type=bottom]");

  put(5, 4, 5, "minecraft:cut_copper_slab[type=top]");
  put(6, 4, 5, "minecraft:copper_block");
  put(7, 4, 5, "minecraft:cut_copper_slab[type=top]");
  put(5, 4, 9, "minecraft:cut_copper_slab[type=top]");
  put(6, 4, 9, "minecraft:copper_block");
  put(7, 4, 9, "minecraft:cut_copper_slab[type=top]");
  put(4, 4, 6, "minecraft:cut_copper_slab[type=top]");
  put(4, 4, 7, "minecraft:copper_block");
  put(4, 4, 8, "minecraft:cut_copper_slab[type=top]");
  put(8, 4, 6, "minecraft:cut_copper_slab[type=top]");
  put(8, 4, 7, "minecraft:copper_block");
  put(8, 4, 8, "minecraft:cut_copper_slab[type=top]");

  put(5, 6, 5, "minecraft:cut_copper_slab[type=bottom]");
  put(6, 6, 5, "minecraft:copper_block");
  put(7, 6, 5, "minecraft:cut_copper_slab[type=bottom]");
  put(5, 6, 9, "minecraft:cut_copper_slab[type=bottom]");
  put(6, 6, 9, "minecraft:copper_block");
  put(7, 6, 9, "minecraft:cut_copper_slab[type=bottom]");

  // Core cap and top plasma injector
  put(6, 7, 7, "minecraft:lodestone");
  put(5, 7, 7, "minecraft:cut_copper_stairs[facing=east,half=bottom]");
  put(7, 7, 7, "minecraft:cut_copper_stairs[facing=west,half=bottom]");
  put(6, 7, 6, "minecraft:cut_copper_stairs[facing=south,half=bottom]");
  put(6, 7, 8, "minecraft:cut_copper_stairs[facing=north,half=bottom]");
  put(5, 7, 6, "minecraft:iron_bars");
  put(7, 7, 6, "minecraft:iron_bars");
  put(5, 7, 8, "minecraft:iron_bars");
  put(7, 7, 8, "minecraft:iron_bars");

  put(6, 8, 7, "minecraft:hopper[facing=down]");
  put(5, 8, 7, "minecraft:iron_bars");
  put(7, 8, 7, "minecraft:iron_bars");
  put(6, 8, 6, "minecraft:iron_bars");
  put(6, 8, 8, "minecraft:iron_bars");

  put(6, 9, 7, "minecraft:lightning_rod[facing=up]");

  // 9. Satellite Uplink Mast & Parabolic Dish (y_rel = 2 to 13)
  put(9, 2, 9, groundPlinth);
  put(9, 3, 9, "minecraft:iron_block");
  put(9, 4, 9, "minecraft:polished_deepslate");
  put(9, 5, 9, "minecraft:polished_deepslate");
  put(9, 6, 9, "minecraft:polished_deepslate");
  put(9, 7, 9, "minecraft:polished_deepslate");
  put(9, 8, 9, "minecraft:iron_bars");
  put(9, 9, 9, "minecraft:iron_bars");
  put(9, 10, 9, "minecraft:iron_bars");
  put(9, 11, 9, "minecraft:iron_bars");
  put(9, 12, 9, "minecraft:lightning_rod[facing=up]");
  put(9, 13, 9, "minecraft:end_rod[facing=up]");

  for (let y = 2; y <= 6; y++) {
    put(9, y, 8, "minecraft:ladder[facing=north]");
  }

  put(10, 2, 9, stoneWall);
  put(9, 2, 10, stoneWall);
  put(10, 3, 9, "minecraft:iron_bars");
  put(9, 3, 10, "minecraft:iron_bars");
  put(10, 4, 9, "minecraft:chain[axis=y]");
  put(9, 4, 10, "minecraft:chain[axis=y]");
  put(10, 5, 9, "minecraft:lightning_rod[facing=up]");
  put(9, 5, 10, "minecraft:lightning_rod[facing=up]");

  // Uplink dish array angled toward the sky
  put(9, 8, 8, "minecraft:iron_bars");
  put(8, 9, 8, "minecraft:polished_deepslate");

  put(8, 10, 8, "minecraft:smooth_stone_slab[type=bottom]");
  put(8, 10, 7, "minecraft:iron_trapdoor[facing=south,half=bottom,open=false]");
  put(7, 10, 8, "minecraft:iron_trapdoor[facing=east,half=bottom,open=false]");
  put(9, 10, 8, "minecraft:iron_trapdoor[facing=west,half=bottom,open=false]");
  put(8, 11, 8, "minecraft:smooth_stone_slab[type=top]");
  put(8, 11, 7, "minecraft:iron_trapdoor[facing=south,half=top,open=false]");

  put(8, 9, 7, "minecraft:end_rod[facing=north]");
  put(8, 9, 6, "minecraft:lightning_rod[facing=north]");

  put(8, 8, 8, "minecraft:chain[axis=y]");
  put(7, 8, 7, "minecraft:iron_bars");

  // 10. Jungle Overgrowth, Vines & Concrete Weathering
  put(1, 2, 2, "minecraft:vine[east=true]");
  put(1, 3, 2, "minecraft:vine[east=true]");
  put(2, 2, 1, "minecraft:vine[south=true]");
  put(2, 3, 1, "minecraft:vine[south=true]");

  put(11, 2, 2, "minecraft:vine[west=true]");
  put(11, 3, 2, "minecraft:vine[west=true]");
  put(10, 2, 1, "minecraft:vine[south=true]");

  put(9, 4, 11, "minecraft:vine[north=true]");
  put(9, 5, 11, "minecraft:vine[north=true]");
  put(11, 2, 9, "minecraft:vine[west=true]");
  put(11, 3, 9, "minecraft:vine[west=true]");

  const leaves = [
    [1, 1, 2], [1, 2, 2], [2, 4, 1], [3, 3, 1],
    [11, 1, 2], [11, 2, 3], [10, 3, 1],
    [1, 1, 9], [1, 2, 10], [2, 4, 10],
    [11, 1, 9], [10, 3, 11], [4, 3, 11]
  ];
  for (const [lx, ly, lz] of leaves) {
    put(lx, ly, lz, "minecraft:jungle_leaves[persistent=true]");
  }

  put(3, 2, 1, "minecraft:moss_carpet");
  put(9, 2, 1, "minecraft:moss_carpet");
  put(1, 1, 4, "minecraft:moss_block");
  put(11, 1, 5, "minecraft:moss_block");
  put(4, 2, 2, "minecraft:moss_carpet");
  put(8, 2, 2, "minecraft:moss_carpet");
  put(3, 2, 9, "minecraft:moss_carpet");
  put(8, 2, 11, "minecraft:moss_carpet");

  return {
    name: "fusion_generator",
    seatY: SY,
    anchors: {
      front: [6, SY + 1, 0],
      console: [6, SY + 1, 2],
      core: [6, SY + 4, 7],
      uplink: [9, SY + 10, 9]
    }
  };
}
